import { useEffect, useState } from "react";

export function useWindowWidth() {
  const [width, setWidth] = useState(() => window.innerWidth);
  useEffect(() => {
    function onResize() { setWidth(window.innerWidth); }   // one reference.
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);   // same reference.
  }, []);
  return width;
}

export function LessonDetails({ lessonId }) {
  const [lesson, setLesson] = useState(null);
  useEffect(() => {
    const controller = new AbortController();
    fetch(`/api/lessons/${lessonId}`, { signal: controller.signal })
      .then((r) => r.json())
      .then(setLesson)
      .catch((e) => { if (e.name !== "AbortError") setLesson({ error: true }); });
    return () => controller.abort();          // the old request can't win.
  }, [lessonId]);
  return lesson ? <h2>{lesson.title}</h2> : <p>Loading...</p>;
}
